package com.kienvo.fonosclone.ui.theme
import androidx.compose.ui.graphics.Color
/** * File tập trung TẤT CẢ màu sắc của ứng dụng * Dễ dàng thay đổi theme và đảm bảo tính nhất quán */ object AppColors {
// ============ GENERAL COLORS ============ val DarkBg = Color(0xFF111218) val PaleYellow = Color(0xFFFFF176) val PaleYellowDark = Color(0xFFFFD54F)
// ============ EBOOK SCREEN COLORS ============ val EbookBgTop = Color(0xFF5D3A29) val EbookBgMid = Color(0xFF3E2723) val EbookBgBottom = Color(0xFF111218) val EbookPurpleBarStart = Color(0xFF422A68) val EbookPurpleBarEnd = Color(0xFF24135F) val EbookBookCardColor = Color(0xFF1E2027) val EbookBorderThin = Color.White.copy(alpha = 0.10f) val EbookSubText = Color(0xFFB6BAC3) val EbookInfinityPink = Color(0xFFD63D8B)
// ============ KIDS SCREEN COLORS ============ // Gradient Hồng cam -> Xanh ngọc -> Xanh lá val KidsGradientPink = Color(0xFFFF8A80) val KidsGradientPinkLight = Color(0xFFF48FB1) val KidsGradientCyan = Color(0xFF80DEEA) val KidsGradientGreen = Color(0xFF69F0AE) }

package com.kienvo.fonosclone.widgets.ebook

import androidx.compose.foundation.background
import androidx.compose.foundation.layout.*
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.drawWithCache
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import com.kienvo.fonosclone.ui.theme.AppColors

/**
 * Background gradient cho màn hình Ebook
 */
@Composable
fun EbookBackground() {
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(
                Brush.verticalGradient(
                    colors = listOf(
                        AppColors.EbookBgTop, 
                        AppColors.EbookBgMid, 
                        AppColors.EbookBgBottom
                    ),
                    startY = 0f, 
                    endY = 1800f
                )
            )
            .drawWithCache {
                val glowPurple = Brush.radialGradient(
                    colors = listOf(
                        Color(0xFFFFAB91).copy(alpha = 0.15f), 
                        Color.Transparent
                    ),
                    center = Offset(size.width * 0.5f, size.height * 0.1f),
                    radius = size.minDimension * 1.5f
                )
                onDrawBehind { drawRect(glowPurple) }
            }
    )
}

package com.kienvo.fonosclone.widgets.ebook
import androidx.compose.foundation.BorderStroke import androidx.compose.foundation.background import androidx.compose.foundation.layout.* import androidx.compose.foundation.shape.RoundedCornerShape import androidx.compose.material3.Surface import androidx.compose.material3.Text import androidx.compose.runtime.Composable import androidx.compose.ui.Alignment import androidx.compose.ui.Modifier import androidx.compose.ui.draw.clip import androidx.compose.ui.geometry.Offset import androidx.compose.ui.graphics.Brush import androidx.compose.ui.graphics.Color import androidx.compose.ui.text.font.FontWeight import androidx.compose.ui.unit.dp import androidx.compose.ui.unit.sp import com.kienvo.fonosclone.ui.theme.AppColors
/** * Banner quảng cáo Ebook Premium * Tái sử dụng được cho các màn hình khác */ @Composable fun EbookBanner() { val shape = RoundedCornerShape(18.dp) Surface( modifier = Modifier .padding(horizontal = 16.dp) .fillMaxWidth() .height(130.dp), shape = shape, color = Color.Transparent, border = BorderStroke(1.dp, AppColors.EbookBorderThin) ) { Box( modifier = Modifier .fillMaxSize() .background( Brush.linearGradient( colors = listOf(Color(0xFFBF360C), Color(0xFF5D4037)), start = Offset(0f, 0f), end = Offset(1000f, 0f) ) ) ) { Row( modifier = Modifier .fillMaxSize() .padding(16.dp), verticalAlignment = Alignment.CenterVertically ) { Box( modifier = Modifier .size(56.dp) .clip(RoundedCornerShape(12.dp)) .background(Color.White.copy(alpha = 0.15f)), contentAlignment = Alignment.Center ) { Text("", fontSize = 32.sp) } Spacer(Modifier.width(16.dp)) Column { Text( "Ebook Premium", color = Color.White, fontSize = 18.sp, fontWeight = FontWeight.Bold ) Spacer(Modifier.height(6.dp)) Text( "Đọc sách không giới hạn với gói\nhội viên Ebook.", color = Color.White.copy(alpha = 0.8f), fontSize = 13.sp, lineHeight = 18.sp ) } } } } }

package com.kienvo.fonosclone.widgets.ebook
import androidx.compose.foundation.BorderStroke import androidx.compose.foundation.background import androidx.compose.foundation.layout.* import androidx.compose.foundation.shape.RoundedCornerShape import androidx.compose.material.icons.Icons import androidx.compose.material.icons.filled.Star import androidx.compose.material3.Icon import androidx.compose.material3.Surface import androidx.compose.material3.Text import androidx.compose.runtime.Composable import androidx.compose.ui.Alignment import androidx.compose.ui.Modifier import androidx.compose.ui.graphics.Color import androidx.compose.ui.layout.ContentScale import androidx.compose.ui.platform.LocalContext import androidx.compose.ui.text.font.FontWeight import androidx.compose.ui.unit.dp import androidx.compose.ui.unit.sp import coil.compose.AsyncImage import coil.request.ImageRequest import com.kienvo.fonosclone.data.SampleData import com.kienvo.fonosclone.ui.theme.AppColors
/** * Card hiển thị thông tin Ebook * Thiết kế: Ảnh dọc + Rating */ @Composable fun EbookCard(book: SampleData.EbookData) { val cardWidth = 148.dp val cardHeight = 275.dp
Surface( modifier = Modifier .width(cardWidth) .height(cardHeight), shape = RoundedCornerShape(12.dp), color = AppColors.EbookBookCardColor, border = BorderStroke(1.dp, AppColors.EbookBorderThin) ) { Column( modifier = Modifier.fillMaxSize() ) { // 1. Ảnh bìa Box( modifier = Modifier .fillMaxWidth() .height(235.dp) ) { AsyncImage( model = ImageRequest.Builder(LocalContext.current) .data(book.coverUrl) .crossfade(true) .build(), contentDescription = null, contentScale = ContentScale.Crop, modifier = Modifier .fillMaxSize() .background(Color.DarkGray) )
// Badge Vô cực Box( modifier = Modifier .align(Alignment.BottomEnd) .padding(8.dp) .size(24.dp) .background( AppColors.EbookInfinityPink, RoundedCornerShape(8.dp) ), contentAlignment = Alignment.Center ) { Text( text = "∞", color = Color.White, fontSize = 14.sp, fontWeight = FontWeight.ExtraBold, modifier = Modifier.offset(y = (-1).dp) ) } }
// 2. Thông tin rating Column( modifier = Modifier .fillMaxWidth() .padding(horizontal = 12.dp, vertical = 4.dp), verticalArrangement = Arrangement.Center, horizontalAlignment = Alignment.Start ) { Spacer(modifier = Modifier.weight(1f)) Row(verticalAlignment = Alignment.CenterVertically) { Icon( Icons.Filled.Star, contentDescription = null, tint = Color(0xFFFFC107), modifier = Modifier.size(16.dp) ) Spacer(Modifier.width(6.dp)) Text( text = "${book.rating}", color = Color.White, fontSize = 14.sp, fontWeight = FontWeight.Bold ) } Spacer(modifier = Modifier.weight(1f)) } } } }

package com.kienvo.fonosclone.widgets.kids
import androidx.compose.foundation.background import androidx.compose.foundation.layout.* import androidx.compose.foundation.shape.RoundedCornerShape import androidx.compose.material.icons.Icons import androidx.compose.material.icons.outlined.Schedule import androidx.compose.material3.Icon import androidx.compose.material3.Text import androidx.compose.runtime.Composable import androidx.compose.ui.Alignment import androidx.compose.ui.Modifier import androidx.compose.ui.draw.clip import androidx.compose.ui.graphics.Color import androidx.compose.ui.layout.ContentScale import androidx.compose.ui.platform.LocalContext import androidx.compose.ui.text.font.FontWeight import androidx.compose.ui.text.style.TextOverflow import androidx.compose.ui.unit.dp import androidx.compose.ui.unit.sp import coil.compose.AsyncImage import coil.request.ImageRequest import com.kienvo.fonosclone.data.SampleData
/** * Card hiển thị truyện thiếu nhi */ @Composable fun KidsStoryCard(story: SampleData.KidStory) { Column { // Ảnh bìa bo tròn AsyncImage( model = ImageRequest.Builder(LocalContext.current) .data(story.imageUrl) .crossfade(true) .build(), contentDescription = null, contentScale = ContentScale.Crop, modifier = Modifier .fillMaxWidth() .aspectRatio(1f) // Hình vuông .clip(RoundedCornerShape(16.dp)) .background(Color.Black.copy(alpha = 0.2f)) )
Spacer(modifier = Modifier.height(8.dp))
// Tên truyện Text( text = story.title, color = Color.White, fontWeight = FontWeight.Bold, fontSize = 15.sp, maxLines = 2, overflow = TextOverflow.Ellipsis, lineHeight = 22.sp )
Spacer(modifier = Modifier.height(4.dp))
// Thời lượng (Icon + Text) Row(verticalAlignment = Alignment.CenterVertically) { Icon( Icons.Outlined.Schedule, contentDescription = null, tint = Color.White.copy(alpha = 0.8f), modifier = Modifier.size(14.dp) ) Spacer(modifier = Modifier.width(4.dp)) Text( text = story.duration, color = Color.White.copy(alpha = 0.8f), fontSize = 13.sp ) } } }
